package com.renthub.booking;
import com.renthub.car.*; import com.renthub.property.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.math.BigDecimal; import java.time.temporal.ChronoUnit; import java.util.*;
@Service public class BookingService {private static final List<String> BLOCKING=List.of("PENDING","CONFIRMED","PAID"); private final BookingRepository repo; private final CarRepository cars; private final PropertyRepository props; public BookingService(BookingRepository r,CarRepository c,PropertyRepository p){repo=r;cars=c;props=p;}
 public Booking create(Long userId,BookingRequest q){if(!q.endDate().isAfter(q.startDate()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"End date must be after start date");String t=q.assetType().trim().toUpperCase();BigDecimal rate=switch(t){case"CAR"->carRate(q.assetId());case"PROPERTY"->propertyRate(q.assetId());default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"assetType must be CAR or PROPERTY");};if(repo.existsByAssetTypeAndAssetIdAndStatusInAndStartDateLessThanAndEndDateGreaterThan(t,q.assetId(),BLOCKING,q.endDate(),q.startDate()))throw new ResponseStatusException(HttpStatus.CONFLICT,"This listing is already booked for the selected dates");long days=ChronoUnit.DAYS.between(q.startDate(),q.endDate());Booking b=new Booking();b.setUserId(userId);b.setAssetType(t);b.setAssetId(q.assetId());b.setStartDate(q.startDate());b.setEndDate(q.endDate());b.setTotalAmount(rate.multiply(BigDecimal.valueOf(days)));b.setStatus("PENDING");return repo.save(b);}
 public Booking cancel(Long userId,Long id,boolean admin){Booking b=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));if(!admin&&!b.getUserId().equals(userId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not your booking");if("PAID".equals(b.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Paid booking cannot be cancelled in this demo flow");b.setStatus("CANCELLED");return repo.save(b);} private BigDecimal carRate(Long id){Car c=cars.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Car not found"));if(!"AVAILABLE".equalsIgnoreCase(c.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Car is not available");return c.getDailyRate();} private BigDecimal propertyRate(Long id){Property p=props.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Property not found"));if(!"AVAILABLE".equalsIgnoreCase(p.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Property is not available");return p.getNightlyRate();}}
